package com.cryptoloan.shared.security;
import io.jsonwebtoken.JwtException;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import org.springframework.http.HttpHeaders;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component class JwtAuthenticationFilter extends OncePerRequestFilter{private final JwtTokenService tokens;JwtAuthenticationFilter(JwtTokenService tokens){this.tokens=tokens;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String value=req.getHeader(HttpHeaders.AUTHORIZATION);if(value!=null&&value.startsWith("Bearer "))try{AuthenticatedUser user=tokens.parse(value.substring(7));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(user,value.substring(7),user.authorities()));}catch(JwtException ignored){SecurityContextHolder.clearContext();}chain.doFilter(req,res);}}

